package org.securemail.client.ecosystem;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.security.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;

/** Actual canonical codecs and Ed25519 typed proofs; no native Mail UI or owner key is substituted. */
class MailAdministrationProtocol600Test {
 KeyPair service,owner,target,device,otherDevice,app;String audience,oid,tid,did,otherDid;long now=System.currentTimeMillis();
 @BeforeEach void setup()throws Exception{service=pair();owner=pair();target=pair();device=pair();otherDevice=pair();app=pair();audience=IdentityProtocol.id(key(service));oid=IdentityProtocol.id(key(owner));tid=IdentityProtocol.id(key(target));did=IdentityProtocol.id(key(device));otherDid=IdentityProtocol.id(key(otherDevice));}
 static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}static byte[] key(KeyPair p){return p.getPublic().getEncoded();}
 String cap(String account,String device){Capability c=new Capability(audience,account,device,App.AEGIS,3,IdentityProtocol.nonce(),now,now+600000,now+600000,key(app),Set.of(Scope.ACCOUNT_READ),new byte[0]);return IdentityProtocol.encodeCapability(c.signed(IdentityProtocol.sign(service.getPrivate(),IdentityProtocol.capabilityBytes(c))));}
 OwnerTransfer transfer(){return new OwnerTransfer(audience,IdentityProtocol.nonce(),oid,did,3,tid,otherDid,3,4,now+120000);}
 FirstDelegation delegation(){return new FirstDelegation(audience,oid,did,3,tid,otherDid,3,"Хранитель ключей",IdentityProtocol.nonce(),now+120000);}
 @Test void bootstrapRequestResultRoundtripIsFixedDomainAndExactAccount()throws Exception{OwnerBootstrap b=new OwnerBootstrap(audience,oid,IdentityProtocol.nonce(),now+300000);var request=new MailPairing600.OwnerBootstrapRequest(cap(oid,did),b,now,IdentityProtocol.nonce(),new byte[64]);var decoded=(MailPairing600.OwnerBootstrapRequest)MailPairing600.decodeRequest(MailPairing600.requestBytes(request));assertArrayEquals(IdentityProtocol.ownerBootstrapBytes(b),IdentityProtocol.ownerBootstrapBytes(decoded.bootstrap()));byte[] proof=IdentityProtocol.sign(owner.getPrivate(),IdentityProtocol.ownerBootstrapBytes(b));var result=MailPairing600.decodeOwnerBootstrapResult(MailPairing600.ownerBootstrapResult(new MailPairing600.OwnerBootstrapResult(key(owner),b,proof)));assertTrue(IdentityProtocol.verify(result.accountPublic(),IdentityProtocol.ownerBootstrapBytes(result.bootstrap()),result.accountProof()));assertThrows(IllegalArgumentException.class,()->new MailPairing600.OwnerBootstrapRequest(cap(tid,otherDid),b,now,IdentityProtocol.nonce(),new byte[64]));assertThrows(IllegalArgumentException.class,()->new MailPairing600.OwnerBootstrapResult(key(target),b,proof));}
 @Test void firstDelegateWireRemainsExistingConsentAndParticipantBound()throws Exception{FirstDelegation d=delegation();assertArrayEquals(IdentityProtocol.firstDelegateConsent(audience,oid,did,3,tid,otherDid,3,d.roleName,d.challenge,d.expiresAt),IdentityProtocol.firstDelegationBytes(d));for(FirstDelegateRole role:FirstDelegateRole.values()){boolean first=role==FirstDelegateRole.OWNER_APPROVE;KeyPair participant=first?owner:target;var request=new MailPairing600.FirstDelegateRequest(cap(first?oid:tid,first?did:otherDid),d,role,now,IdentityProtocol.nonce(),new byte[64]);var decoded=(MailPairing600.FirstDelegateRequest)MailPairing600.decodeRequest(MailPairing600.requestBytes(request));assertEquals(role,decoded.intent());byte[] proof=IdentityProtocol.sign(participant.getPrivate(),IdentityProtocol.firstDelegationBytes(d));var result=MailPairing600.decodeFirstDelegateResult(MailPairing600.firstDelegateResult(new MailPairing600.FirstDelegateResult(key(participant),d,role,proof)));assertTrue(IdentityProtocol.verify(result.accountPublic(),IdentityProtocol.firstDelegationBytes(result.delegation()),result.accountProof()));}assertThrows(IllegalArgumentException.class,()->new MailPairing600.FirstDelegateRequest(cap(oid,did),d,FirstDelegateRole.DELEGATE_ACCEPT,now,IdentityProtocol.nonce(),new byte[64]));}
 @Test void ownerTransferConsentDistinguishesOwnerAndSuccessor()throws Exception{OwnerTransfer t=transfer();for(OwnerTransferRole role:OwnerTransferRole.values()){boolean first=role==OwnerTransferRole.OWNER_APPROVE;KeyPair participant=first?owner:target;var request=new MailPairing600.OwnerTransferRequest(cap(first?oid:tid,first?did:otherDid),t,role,now,IdentityProtocol.nonce(),new byte[64]);var decoded=(MailPairing600.OwnerTransferRequest)MailPairing600.decodeRequest(MailPairing600.requestBytes(request));assertEquals(role,decoded.intent());byte[] proof=IdentityProtocol.sign(participant.getPrivate(),IdentityProtocol.ownerTransferConsent(t,role));var result=MailPairing600.decodeOwnerTransferResult(MailPairing600.ownerTransferResult(new MailPairing600.OwnerTransferResult(key(participant),t,role,proof)));assertTrue(IdentityProtocol.verify(result.accountPublic(),IdentityProtocol.ownerTransferConsent(result.transfer(),role),result.accountProof()));assertFalse(IdentityProtocol.verify(result.accountPublic(),IdentityProtocol.ownerTransferConsent(result.transfer(),first?OwnerTransferRole.SUCCESSOR_ACCEPT:OwnerTransferRole.OWNER_APPROVE),result.accountProof()));}assertThrows(IllegalArgumentException.class,()->new MailPairing600.OwnerTransferRequest(cap(oid,did),t,OwnerTransferRole.SUCCESSOR_ACCEPT,now,IdentityProtocol.nonce(),new byte[64]));}
 @Test void requestsAndResultsRejectTrailingOversizedAndCrossPurposePayloads()throws Exception{OwnerBootstrap b=new OwnerBootstrap(audience,oid,IdentityProtocol.nonce(),now+300000);byte[] request=MailPairing600.requestBytes(new MailPairing600.OwnerBootstrapRequest(cap(oid,did),b,now,IdentityProtocol.nonce(),new byte[64]));assertThrows(IOException.class,()->MailPairing600.decodeRequest(Arrays.copyOf(request,request.length+1)));assertThrows(IOException.class,()->MailPairing600.decodeRequest(new byte[8193]));byte[] result=MailPairing600.ownerBootstrapResult(new MailPairing600.OwnerBootstrapResult(key(owner),b,IdentityProtocol.sign(owner.getPrivate(),IdentityProtocol.ownerBootstrapBytes(b))));assertThrows(IOException.class,()->MailPairing600.decodeOwnerTransferResult(result));assertThrows(IOException.class,()->MailPairing600.decodeFirstDelegateResult(result));assertThrows(IOException.class,()->MailPairing600.decodeOwnerBootstrapResult(Arrays.copyOf(result,result.length+1)));}
 @Test void unknownDeviceRecoveryRequestAndDualPublicProofResultRoundtrip()throws Exception{KeyPair recoveryKey=pair();DeviceRecovery r=new DeviceRecovery(audience,oid,key(device),IdentityProtocol.nonce(),now+300000);String n=IdentityProtocol.nonce();byte[] proof=IdentityProtocol.sign(device.getPrivate(),IdentityProtocol.deviceRecoveryInspection(r,now,n));var decoded=(MailPairing600.DeviceRecoveryRequest)MailPairing600.decodeRequest(MailPairing600.requestBytes(new MailPairing600.DeviceRecoveryRequest(r,now,n,proof)));assertArrayEquals(IdentityProtocol.recovery(audience,oid,r.challenge,key(device),r.expiresAt),IdentityProtocol.deviceRecoveryBytes(decoded.recovery()));byte[] b=IdentityProtocol.deviceRecoveryBytes(r);var result=MailPairing600.decodeDeviceRecoveryResult(MailPairing600.deviceRecoveryResult(new MailPairing600.DeviceRecoveryResult(key(owner),key(recoveryKey),r,IdentityProtocol.sign(owner.getPrivate(),b),IdentityProtocol.sign(recoveryKey.getPrivate(),b))));assertTrue(IdentityProtocol.verify(result.accountPublic(),b,result.accountProof()));assertTrue(IdentityProtocol.verify(result.recoveryPublic(),b,result.recoveryProof()));assertThrows(IOException.class,()->MailPairing600.decodeOwnerBootstrapResult(MailPairing600.deviceRecoveryResult(result)));}
 @Test void recoveryPurposeRejectsWrongDeviceProofRootAndCombinedKey()throws Exception{DeviceRecovery r=new DeviceRecovery(audience,oid,key(device),IdentityProtocol.nonce(),now+300000);String n=IdentityProtocol.nonce();assertThrows(IllegalArgumentException.class,()->new MailPairing600.DeviceRecoveryRequest(r,now,n,IdentityProtocol.sign(otherDevice.getPrivate(),IdentityProtocol.deviceRecoveryInspection(r,now,n))));byte[] b=IdentityProtocol.deviceRecoveryBytes(r),proof=IdentityProtocol.sign(owner.getPrivate(),b);assertThrows(IllegalArgumentException.class,()->new MailPairing600.DeviceRecoveryResult(key(target),key(app),r,proof,proof));assertThrows(IllegalArgumentException.class,()->new MailPairing600.DeviceRecoveryResult(key(owner),key(owner),r,proof,proof));byte[] key=r.newDevicePublic();key[0]^=1;assertArrayEquals(key(device),r.newDevicePublic());}
 @Test void publicConsentResultNeverCarriesAnAccountPrivateKey()throws Exception{OwnerTransfer t=transfer();byte[] privateBytes=owner.getPrivate().getEncoded(),proof=IdentityProtocol.sign(owner.getPrivate(),IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.OWNER_APPROVE));byte[] result=MailPairing600.ownerTransferResult(new MailPairing600.OwnerTransferResult(key(owner),t,OwnerTransferRole.OWNER_APPROVE,proof));assertTrue(result.length<2048);boolean found=false;for(int offset=0;offset+privateBytes.length<=result.length;offset++)if(Arrays.equals(privateBytes,Arrays.copyOfRange(result,offset,offset+privateBytes.length))){found=true;break;}assertFalse(found);Arrays.fill(privateBytes,(byte)0);}
}
